package com.example.payment.architecturetest;

import static com.tngtech.archunit.lang.syntax.ArchRuleDefinition.noClasses;

import com.tngtech.archunit.core.importer.ImportOption;
import com.tngtech.archunit.junit.AnalyzeClasses;
import com.tngtech.archunit.junit.ArchTest;
import com.tngtech.archunit.lang.ArchRule;

@AnalyzeClasses(packages = "com.example.payment", importOptions = ImportOption.DoNotIncludeTests.class)
class LayerRulesTest {

    @ArchTest
    static final ArchRule domainDependsOnNoOtherLayer = noClasses()
            .that().resideInAPackage("..payment.domain..")
            .should().dependOnClassesThat().resideInAnyPackage("..payment.application..", "..payment.infrastructure..", "..payment.app..");

    @ArchTest
    static final ArchRule applicationDoesNotDependOnOuterLayers = noClasses()
            .that().resideInAPackage("..payment.application..")
            .should().dependOnClassesThat().resideInAnyPackage("..payment.infrastructure..", "..payment.app..");

    @ArchTest
    static final ArchRule infrastructureDoesNotDependOnApp = noClasses()
            .that().resideInAPackage("..payment.infrastructure..")
            .should().dependOnClassesThat().resideInAPackage("..payment.app..");

    @ArchTest
    static final ArchRule businessCodeIsFreeOfTechnicalFrameworks = noClasses()
            .that().resideInAnyPackage("..payment.domain..", "..payment.application..")
            .should().dependOnClassesThat().resideInAnyPackage(
                    "org.springframework..", "com.fasterxml..", "java.net..", "java.nio.file..", "java.io..", "java.sql..", "javax.sql..");
}
E
mvn -o -q verify 2>&1 | tail -30

